import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { NotificationProvider } from './contexts/NotificationContext';
import Navigation from './components/Navigation';
import Dashboard from './components/Dashboard';
import ConfigurationWizard from './components/ConfigurationWizard';
import AlertsPanel from './components/AlertsPanel';
import DMARCReportsPanel from './components/DMARCReportsPanel';
import DNSStatusPanel from './components/DNSStatusPanel';
import UserSettings from './components/UserSettings';

function App() {
  return (
    <NotificationProvider>
      <Router>
        <div className="min-h-screen bg-gray-50">
          <Navigation />
          <main>
            <Routes>
              <Route path="/" element={<Dashboard />} />
              <Route path="/domains" element={<DNSStatusPanel />} />
              <Route path="/reports" element={<DMARCReportsPanel />} />
              <Route path="/alerts" element={<AlertsPanel />} />
              <Route path="/settings" element={<div className="py-6"><div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8"><h1 className="text-3xl font-bold text-gray-900">Configuraciones</h1><p className="mt-2 text-gray-600">Esta sección será implementada en futuras fases.</p></div></div>} />
              <Route path="/wizard" element={<ConfigurationWizard />} />
            </Routes>
          </main>
        </div>
      </Router>
    </NotificationProvider>
  );
}

export default App;
